mapper.select:
SELECT tm.*, u.user_name, u.avatar, u.age, u.sex, tss.`name` as scenicSpotName, tss.location, s.name as shopName FROM travel_moments tm LEFT JOIN tb_user u ON tm.user_id = u.user_id left join travel_scenic_spot tss on tm.scenic_spot_id = tss.id left join travel_shop s on tm.shop_id = s.id
and tm.user_id = #{param.userId}
and tm.title like concat('%', #{param.title} ,'%')
and tm.province = #{param.province}
and tm.city = #{param.city}
and tm.district = #{param.district}
and tm.scenic_spot_id = #{param.scenicSpotId}
and tss.name like concat('%', #{param.scenicSpotName} ,'%')
and tm.audit_status = #{param.auditStatus}
and tm.shop_id = #{param.shopId}
and u.user_name like concat('%', #{param.userName} ,'%')
order by tm.create_time desc
